# Rebuild the graph with actual edges
graph = {}
for line in actual_edges_text.strip().split('\n'):
    if '->' in line:
        parts = line.split('->')
        source = parts[0].strip()
        target = parts[1].strip()
        if source not in graph:
            graph[source] = []
        graph[source].append(target)

print(f"Total nodes with outgoing edges: {len(graph)}")

# BFS from node 9bf31c7ff0, find nodes at exactly depth 4
start_node = "9bf31c7ff0"

from collections import deque

queue = deque([(start_node, 0)])  # (node, depth)
visited = {start_node}
depth_map = {0: {start_node}}

while queue:
    node, depth = queue.popleft()
    if depth >= 4:
        continue
    if node in graph:
        for neighbor in graph[node]:
            if neighbor not in visited:
                visited.add(neighbor)
                new_depth = depth + 1
                if new_depth not in depth_map:
                    depth_map[new_depth] = set()
                depth_map[new_depth].add(neighbor)
                queue.append((neighbor, new_depth))

print(f"\nDepth 0: {sorted(depth_map.get(0, set()))}")
print(f"Depth 1: {sorted(depth_map.get(1, set()))}")
print(f"Depth 2: {sorted(depth_map.get(2, set()))}")
print(f"Depth 3: {sorted(depth_map.get(3, set()))}")
print(f"Depth 4: {sorted(depth_map.get(4, set()))}")

depth_4_nodes = sorted(depth_map.get(4, set()))
print(f"\nDepth 4 nodes (sorted): {depth_4_nodes}")
print(f"\nNumber of nodes at depth 4: {len(depth_4_nodes)}")
